import React from 'react';

export function Avatar({ name, status }: { name: string; status?: 'online' | 'busy' | 'offline' }) {
  const initials = name.split(' ').map((p) => p[0]).slice(0, 2).join('').toUpperCase();
  const dot = status === 'online' ? '{{token:colors.accent.success}}' : status === 'busy' ? '{{token:colors.accent.warning}}' : '{{token:colors.text.muted}}';
  return (
    <span style={{ position: 'relative', display: 'inline-flex' }} aria-label={name}>
      <span style={{ width: '40px', height: '40px', borderRadius: '50%', background: '{{token:colors.accent.primary}}', color: '{{token:colors.text.inverse}}', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 600, fontSize: '{{token:typography.scale.sm}}' }}>{initials}</span>
      {status ? <span style={{ position: 'absolute', bottom: 0, right: 0, width: '10px', height: '10px', borderRadius: '50%', background: dot, border: '2px solid {{token:colors.base.surface}}' }} /> : null}
    </span>
  );
}
